import Handlebars from 'handlebars';
import substr from '../helper/string/substr';

Handlebars.registerHelper('substr', substr);

describe('substr helper', () => {
    it('should return the full string if max is not defined and length is within default', () => {
        const template = Handlebars.compile('{{substr name}}');
        const result = template({ name: 'Hello, world!' });
        expect(result).toBe('Hello, world!');
    });

    it('should truncate the string to the specified max length', () => {
        const template = Handlebars.compile('{{substr name max=5}}');
        const result = template({ name: 'Hello, world!' });
        expect(result).toBe('Hello');
    });

    it('should start truncation from a specified position', () => {
        const template = Handlebars.compile('{{substr name from=7 max=5}}');
        const result = template({ name: 'Hello, world!' });
        expect(result).toBe('world');
    });

    it('should append the unit if opt.unit is specified and string is truncated', () => {
        const template = Handlebars.compile('{{substr name max=5 unit="..."}}');
        const result = template({ name: 'Hello, world!' });
        expect(result).toBe('Hello...');
    });

    it('should not append the unit if string length is less than or equal to max', () => {
        const template = Handlebars.compile('{{substr name max=10 unit="..."}}');
        const result = template({ name: 'Hello' });
        expect(result).toBe('Hello');
    });

    it('should handle an empty string gracefully', () => {
        const template = Handlebars.compile('{{substr name max=5}}');
        const result = template({ name: '' });
        expect(result).toBe('');
    });

    it('should handle non-string data by converting it to string', () => {
        const template = Handlebars.compile('{{substr name max=4}}');
        const result = template({ name: 123456 });
        expect(result).toBe('1234');
    });

    it('should return an empty string if data is null', () => {
        const template = Handlebars.compile('{{substr name max=5}}');
        const result = template({ name: null });
        expect(result).toBe('');
      });
    
      it('should return an empty string if data is undefined', () => {
        const template = Handlebars.compile('{{substr name max=5}}');
        const result = template({ name: undefined });
        expect(result).toBe('');
      });
});
